import Foundation
import SwiftData
import SwiftUI

enum PersistenceCoding {
    private static let encoder = JSONEncoder()
    private static let decoder = JSONDecoder()

    static func encode<T: Codable>(_ value: T) -> Data {
        do {
            return try encoder.encode(value)
        } catch {
            assertionFailure("Failed to encode value of type \(T.self): \(error)")
            return Data()
        }
    }

    static func decode<T: Codable>(_ type: T.Type, from data: Data) -> T? {
        guard !data.isEmpty else { return nil }
        do {
            return try decoder.decode(T.self, from: data)
        } catch {
            assertionFailure("Failed to decode value of type \(T.self): \(error)")
            return nil
        }
    }
}

